custom_css:
/* 一號展廳 · 夜 · by kyuu */

/* ── 字体声明（本地优先，无网络请求） ── */
@font-face {
  font-family: 'Cormorant Garamond';
  src: local('Cormorant Garamond'), local('CormorantGaramond-Regular');
  font-weight: 400; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Cormorant Garamond';
  src: local('Cormorant Garamond SemiBold'), local('CormorantGaramond-SemiBold');
  font-weight: 600; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Cormorant Garamond';
  src: local('Cormorant Garamond Italic'), local('CormorantGaramond-Italic');
  font-weight: 400; font-style: italic; font-display: swap;
}
@font-face {
  font-family: 'LXGW WenKai';
  src: local('LXGW WenKai'), local('LXGWWenKai-Regular');
  font-weight: 400; font-style: normal; font-display: swap;
}

/* ── 设计变量 ── */
:root {
  --bg: #060607;
  --card: #0C0C0E;
  --ink: #A8A8B2;
  --meta: #6A6A74;
  --name: #C4C4CE;
  --line: #1C1C20;
  --accent: #2A2A30;
  --sans: ui-sans-serif, system-ui, -apple-system, sans-serif;
  --serif: 'Cormorant Garamond', serif;
  --cjk: 'LXGW WenKai', serif;

  --card-pad: 2.2rem;
  --name-indent: 7.875rem;
  --meta-x: 10.1rem;
  --timer-x: 12.8rem;

  font-size: clamp(12px, 0.8vw + 9px, 15px) !important;

  --SmartThemeBodyColor: #A8A8B2;
  --SmartThemeBorderColor: #1C1C20;
  --SmartThemeBlurTintColor: #0C0C0E;
  --SmartThemeChatTintColor: transparent;
  --SmartThemeQuoteColor: #6A6A74;
  --SmartThemeFastUIBGColor: #0C0C0E;
  --SmartThemeUserMesBlurTintColor: #0C0C0E;
  --SmartThemeBotMesBlurTintColor: #0C0C0E;
  --SmartThemeEmColor: #8A8A94;
  --SmartThemeShadowColor: rgba(0,0,0,.4);
}

/* ── 移动端适配 ── */
@media (max-width: 768px) and (pointer: coarse) {
  :root { font-size: clamp(12px, 1vw + 9px, 14px) !important; }
  #chat { padding: 1.5rem 0.25rem !important; }
  #chat .mes { max-width: 98% !important; margin-bottom: 2rem; padding: 1.5rem 0.8rem !important; }
  #chat .mes .mes_text { margin-left: 0; padding-left: 0.6rem; padding-right: 0.4rem; }
  #send_textarea { min-height: 1.2rem !important; font-size: 0.9rem !important; }
  #send_form { padding: 0.02rem 0.5rem !important; }
  #form_sheld { padding: 0 !important; }
}

/* ── 全局（透出酒馆背景图） ── */
body, body #sheld { background: transparent !important }

:is(.drawer-content, #top-settings-holder, #right-nav-panel, #left-nav-panel,
#WorldInfo, .dialogue_popup, .dialogue_popup_large, #dialogue_popup,
#shadow_popup, .popup:not(.tobepurged), .ui-widget-content, #select_chat_popup,
#character_popup, #export_format_popup, .openai_logit_bias_list,
#movingUIPresets, .list-group, .text_pole_row) {
  background: var(--card) !important;
}

:is(#top-bar, #form_sheld, #send_form, .range-block, .range-block-title,
.title_restorable, h3, h4, .menu_button, .drawer-icon,
textarea, input[type="text"], select,
.mes_reasoning_details, .mes_reasoning_details summary) {
  background: var(--card) !important;
  background-image: none !important;
  color: var(--ink) !important;
  border-color: var(--line) !important;
  text-shadow: none !important;
}

:is(#top-bar, #form_sheld, .drawer-content, #right-nav-panel,
#left-nav-panel, .menu_button, .range-block) *:not([class*="fa-"]) {
  color: var(--ink) !important;
}

/* ── 选中文字样式 ── */
::selection {
  background: rgba(168, 168, 178, 0.25) !important;
  color: #E0E0EA !important;
  text-shadow: none !important;
}
::-moz-selection {
  background: rgba(168, 168, 178, 0.25) !important;
  color: #E0E0EA !important;
  text-shadow: none !important;
}

/* ── 抽屉/按钮悬浮 ── */
:is(.inline-drawer-toggle, .inline-drawer-header,
.menu_button, .drawer-icon):hover {
  background: #141418 !important;
  color: var(--name) !important;
}

/* ── 聊天容器 ── */
#chat {
  display: flex; flex-direction: column; align-items: center;
  padding: 3.75rem 1.25rem;
  background: rgba(6, 6, 7, 0.65);
}

/* ── 卡片 ── */
#chat .mes {
  display: block !important;
  position: relative !important;
  width: 100%; max-width: 94%;
  background: rgba(12, 12, 14, 0.88) !important;
  border: 1px solid #141418; border-radius: 2px;
  box-shadow: 0 0.625rem 3rem rgba(0,0,0,.5);
  padding: var(--card-pad) !important;
  margin: 0 0 3.75rem;
  box-sizing: border-box;
  min-height: unset; overflow: visible;
}

/* ── 消息选中反馈（删除/移动时） ── */
#chat .mes.selected {
  background: rgba(180, 60, 60, 0.15) !important;
  border-color: rgba(180, 60, 60, 0.3) !important;
  box-shadow: inset 0 0 0 1px rgba(180, 60, 60, 0.2) !important;
  transition: background 0.15s ease;
}

/* ── 头像 ── */
#chat .mes .mesAvatarWrapper { display: contents !important }

#chat .mes .avatar {
  position: absolute !important;
  top: var(--card-pad); left: var(--card-pad);
  width: 5.25rem; height: 7rem;
  border-radius: 0; border: 1px solid #252528;
  padding: 0.375rem; background: #0A0A0C;
  box-shadow: 0.125rem 0.25rem 0.75rem rgba(0,0,0,.3);
  box-sizing: content-box; overflow: hidden; z-index: 10;
}

#chat .mes .avatar img {
  width: 100%; height: 100%; object-fit: cover;
  border-radius: 0; border: none; display: block;
}

#chat .mes :is(.mesIDDisplay, .ch_name .mes_ghost) { display: none !important }

#chat .mes::after {
  content: 'ID.' attr(mesid);
  position: absolute;
  top: calc(var(--card-pad) + 7.875rem + 0.5rem);
  left: var(--card-pad); width: 6.125rem; text-align: center;
  font: 0.6rem/1 var(--sans); color: #3E3E44;
  letter-spacing: .08em; pointer-events: none;
}

/* ── 内容块 ── */
#chat .mes .mes_block {
  position: static; display: block; width: 100%;
  padding: 0; margin: 0; min-height: auto;
  background: none; border: none; box-shadow: none;
}

/* ── 名字区域 ── */
#chat .mes .ch_name {
  display: block; position: static;
  padding: 0 0 1.25rem var(--name-indent);
  min-height: 10.2rem;
  border-bottom: 1px solid var(--line);
  margin: 0; width: 100%; box-sizing: border-box; overflow: visible;
}

#chat .mes .ch_name .flex-container {
  display: flex; flex-direction: column;
  align-items: flex-start; gap: 0.375rem;
}

#chat .mes .ch_name .name_text {
  font: 600 1.35rem/1.2 var(--serif);
  color: var(--name); letter-spacing: .06em; text-shadow: none;
}

/* ── 数据行 ── */
#chat .mes :is(.tokenCounterDisplay, .mes_timer, .timestamp) {
  margin: 0 !important; padding: 0 !important;
  border: none !important; background: none !important;
  font: 400 0.75rem/1.4 var(--cjk) !important;
  color: var(--meta) !important;
  letter-spacing: .03em;
  white-space: nowrap;
  display: inline-block !important;
  position: absolute !important;
  z-index: 5;
}

#chat .mes .tokenCounterDisplay {
  top: 4.2rem !important; left: var(--meta-x) !important;
}

#chat .mes .mes_timer {
  top: 4.2rem !important; left: var(--timer-x) !important;
}
#chat .mes .mes_timer::before {
  content: '|';
  color: #2E2E34;
  font: 400 0.6rem/1 var(--cjk);
  margin-right: 0.25rem;
}

#chat .mes .timestamp {
  top: 5.6rem !important; left: var(--meta-x) !important;
  opacity: 1 !important;
}

/* 签名 */
#chat .mes .ch_name::after {
  content: '✦ 却只在你的阴影中找到安宁\A Comme il pleut sur la ville.';
  position: absolute;
  top: 7.2rem; left: var(--meta-x);
  white-space: pre-line;
  font: italic 0.75rem/1.8 var(--serif), var(--cjk);
  color: #4E4E58; letter-spacing: .05em;
}

/* ── 按钮 ── */
#chat .mes :is(.mes_buttons, .mes_edit_buttons) {
  position: absolute !important;
  right: var(--card-pad);
  top: calc(var(--card-pad) + 7.875rem);
  z-index: 20;
  flex-direction: row; align-items: center; float: none;
}
#chat .mes .mes_buttons { display: flex; gap: 0.5rem; opacity: .25 }
#chat .mes .mes_edit_buttons {
  gap: 0.35rem; padding: 0; background: none;
  border: none; border-radius: 0; box-shadow: none; opacity: .4;
}

/* ── 正文 ── */
#chat .mes .mes_text {
  margin: 1.5rem 0 0 0.5rem; padding-left: 1.375rem;
  border-left: 2px solid var(--accent);
  font: 0.95rem/1.6 var(--cjk); color: var(--ink); text-align: justify;
}

#chat .mes .mes_text :is(blockquote, q) {
  border-left: 2px solid #252528; background: #0A0A0C;
  padding: 0.05rem 0.6rem; margin: 0.05rem 0; color: #7A7A84; border-radius: 0;
  box-shadow: none !important;
  line-height: 1.4;
}
#chat .mes .mes_text code {
  font-size: 0.75rem; background: #141418;
  padding: 0.0625rem 0.3125rem; border-radius: 0.125rem; color: #9898A2;
}
#chat .mes .mes_text :is(em, i) { color: #8A8A94 }
#chat .mes .mes_text :is(strong, b) { color: #D0D0DA; font-weight: 700 }
#chat .mes .mes_text :is(s, del) { color: #3E3E44; text-decoration-color: #3E3E44 }

/* ── 输入区域 ── */
#form_sheld {
  width: 100% !important;
  max-width: none !important;
  margin: 0;
  background: rgba(12, 12, 14, 0.88) !important;
  border-top: 1px solid var(--line);
  box-shadow: 0 -0.125rem 0.75rem rgba(0,0,0,.3);
}

#send_form {
  width: 100%;
  max-width: none !important;
  padding: 0.05rem 0.95rem;
  background: transparent !important;
}

#send_textarea {
  flex-grow: 1;
  min-height: 1.72rem;
  padding: 0.22rem 0.16rem;
  background: transparent !important;
  border: 0 !important;
  outline: none;
  color: var(--ink) !important;
  font: 1rem/1.3 var(--cjk) !important;
  resize: none;
}

#send_textarea::placeholder {
  color: #4E4E58 !important;
  font: italic 0.82rem var(--cjk) !important;
}

/* ── 翻页 ── */
#chat .mes .mes_bottom { padding: 0; margin-top: 0.5rem }
#chat .mes :is(.swipe_right, .swipe_left) { color: #3E3E44 }
#chat .mes .swipes-counter { font: 0.64rem var(--sans); color: #3E3E44 }

/* ── 颜色覆盖 ── */
a, a:visited, a:active { color: var(--meta) !important; text-decoration: none !important }
a:hover { color: var(--name) !important }

:is(.menu_button, #options_button, #extensionsMenuButton,
.mes_stop, #dialogue_del_mes, #rightSendForm > div,
#leftSendForm > div) {
  color: var(--meta) !important;
}

:is(.list-group-item, .ctx-item, .ctx-header, .ctx-menu) {
  color: var(--ink) !important;
  background: var(--card) !important;
}
:is(.list-group-item, .ctx-item):hover {
  background: #141418 !important;
}

/* 暂停键 */
.mes_stop {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* ── 顶栏 ── */
#top-bar {
  background: rgba(12, 12, 14, 0.88) !important;
}

/* ── 修复抽屉/弹出层透底 ── */
#options,
#options .options-content,
.drawer-content,
.popup,
#shadow_popup,
#dialogue_popup,
.dialogue_popup,
.dialogue_popup_large,
#select_chat_popup,
#character_popup {
  background: var(--card) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  opacity: 1 !important;
}

#sheld, #top-settings-holder {
  background: transparent !important;
  backdrop-filter: none !important;
}

.select_chat_block,
.bogus_folder_select {
  background: #141418 !important;
  border-color: var(--line) !important;
}

/* ── 图标替换 ── */

/* 合并隐藏原图标 */
:is(#send_but, #mes_stop > i, #option_regenerate,
#leftNavDrawerIcon, #rightNavDrawerIcon,
#top-settings-holder .drawer-icon,
#extensionsMenuButton, #options_button,
#chat .mes .mes_edit)::before {
  content: none !important;
}

/* 顶栏图标 */
#top-settings-holder .drawer-icon {
  font-size: 0 !important;
  width: 3.8rem !important; height: 3.8rem !important;
  background: transparent !important;
  border: none !important;
  background-image: url('https://files.catbox.moe/qiqbn9.png') !important;
  background-size: contain !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  opacity: 0.35;
  transition: opacity 0.2s, transform 0.2s;
}
#top-settings-holder .drawer-icon:hover { opacity: 0.7; transform: scale(1.1) }
#top-settings-holder .drawer-icon * { display: none !important }

/* 发送 */
#send_but {
  font-size: 0 !important;
  width: 3rem !important; height: 3rem !important;
  background: url('https://files.catbox.moe/a7020v.png') center/contain no-repeat !important;
  opacity: 0.55; transition: opacity 0.2s;
}
#send_but:hover { opacity: 0.9 }

/* 暂停 */
#mes_stop > i {
  font-size: 0 !important;
  color: transparent !important;
  display: inline-block !important;
  width: 1.8rem !important; height: 1.8rem !important;
  background: url('https://files.catbox.moe/y48ri8.png') center/contain no-repeat !important;
}

/* 扩展菜单 */
#extensionsMenuButton {
  font-size: 0 !important;
  width: 2.2rem !important; height: 2.2rem !important;
  background: url('https://files.catbox.moe/brmk5n.png') center/contain no-repeat !important;
  border: none !important;
  opacity: 0.5; transition: opacity 0.2s;
}
#extensionsMenuButton:hover { opacity: 0.85 }

/* 展开菜单 */
#options_button {
  font-size: 0 !important;
  width: 2.2rem !important; height: 2.2rem !important;
  background: url('https://files.catbox.moe/brmk5n.png') center/contain no-repeat !important;
  border: none !important;
  opacity: 0.5; transition: opacity 0.2s;
}
#options_button:hover { opacity: 0.85 }

/* 编辑按钮 */
#chat .mes .mes_edit {
  font-size: 0 !important;
  width: 2.2rem !important; height: 2.2rem !important;
  background: url('https://files.catbox.moe/wawtdk.png') center/contain no-repeat !important;
  opacity: 0.4; transition: opacity 0.2s;
}
#chat .mes .mes_edit:hover { opacity: 0.8 }

/* 翻页 */
.swipe_left, .swipe_right {
  font-size: 0 !important;
  width: 1.8rem !important; height: 1.8rem !important;
  background: url('https://files.catbox.moe/s2ohcy.png') center/contain no-repeat !important;
  background-color: transparent !important;
  opacity: 0.4; transition: opacity 0.2s, transform 0.2s;
}
.swipe_left { transform: translateY(1rem) }
.swipe_left:hover { opacity: 0.75; transform: translateY(1rem) scale(1.1) }
.swipe_right { transform: scaleX(-1) translateY(1rem) }
.swipe_right:hover { opacity: 0.75; transform: scaleX(-1) translateY(1rem) scale(1.1) }

/* ── 移动端图标 ── */
@media (max-width: 768px) and (pointer: coarse) {
  #top-settings-holder .drawer-icon {
    width: 2.4rem !important; height: 2.4rem !important;
    background-size: contain !important;
  }
}

/* ── 推理 / 思考区块 ── */
#chat .mes_reasoning_arrow { display: none; }

#chat .mes_reasoning_details {
  margin: 1rem 0 0.2rem 0.5rem;
  padding: 0;
  border-left: 2px solid var(--line);
  border-radius: 0;
  background: transparent !important;
  box-shadow: none !important;
}

#chat .mes_reasoning_details summary,
#chat .mes_reasoning_header {
  padding: 0.4rem 0.85rem;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  cursor: pointer;
}

#chat .mes_reasoning_header .mes_reasoning_header_title { font-size: 0; }

#chat .mes_reasoning_header .mes_reasoning_header_title::before {
  content: '✦ Pensée';
  color: #3E3E44;
  font: italic 0.72rem/1 var(--serif);
  letter-spacing: 0.12em;
}

#chat .mes_reasoning {
  padding: 0.5rem 1rem;
  border-top: 1px dashed #1C1C20;
  color: #5A5A64;
  font: 0.78rem/1.55 var(--cjk);
  letter-spacing: 0.01em;
}

#chat .mes_reasoning :is(em, i) { color: #4E4E58; }
#chat .mes_reasoning :is(strong, b) { color: #7A7A84; font-weight: 600; }

/* ── QR 悬停滑出 ── */
#qr--bar {
  max-height: 0 !important;
  overflow: hidden !important;
  background: none !important;
  transition: max-height 0.5s ease, padding 0.5s ease;
  padding: 0 !important;
}

#form_sheld:hover #qr--bar {
  max-height: 80px !important;
  padding: 0.3rem 0.5rem !important;
}
